from openpyxl import load_workbook
from datetime import datetime, timedelta
import re

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Step 1: Identify the header and data ranges
# Find the header row (row with "Group A")
header_row = None
for row in ws.iter_rows(min_row=1, max_row=261):
    if row[0].value == "Group A":
        header_row = row[0].row
        break

# Find the first data row (row with "1951-01")
first_data_row = None
for row in ws.iter_rows(min_row=header_row + 1, max_row=261):
    if row[0].value.startswith("1951-"):
        first_data_row = row[0].row
        break

# Find the last data row (row with "1951-11")
last_data_row = None
for row in ws.iter_rows(min_row=header_row + 1, max_row=261):
    if row[0].value.startswith("1951-11"):
        last_data_row = row[0].row
        break

# Find the column indices for the data columns (columns 1 to 19)
data_cols = []
for col in range(1, 20):
    data_cols.append(col)

# Step 2: Extract data from Group A
group_a_data = []
for row in ws.iter_rows(min_row=first_data_row, max_row=last_data_row, min_col=1, max_col=1):
    date_str = row[0].value
    if date_str:
        group_a_data.append({
            "date": date_str,
            "values": []
        })

for col in data_cols:
    for row in ws.iter_rows(min_row=first_data_row, max_row=last_data_row, min_col=col, max_col=col):
        value = row[0].value
        if value is not None:
            group_a_data[-1]["values"].append(value)

# Step 3: Process data to convert from Group A to Group B
group_b_data = []
for entry in group_a_data:
    date_str = entry["date"]
    values = entry["values"]

    # Parse the date
    date_parts = date_str.split("-")
    year = int(date_parts[0])
    month = int(date_parts[1])

    # Generate all dates for the month
    start_date = datetime(year, month, 1)
    end_date = datetime(year, month + 1, 1)

    current_date = start_date
    while current_date < end_date:
        # Format the date as "YYYY-MM-DD"
        formatted_date = current_date.strftime("%Y-%m-%d")

        # Find the value for this date
        value = None
        for i, val in enumerate(values):
            if val is not None:
                if isinstance(val, str) and val == "NA":
                    value = None
                    break
                elif isinstance(val, str) and val in ["-9999", "M"]:
                    value = None
                    break
                else:
                    value = val
                    break

        # Handle the value
        if value is None:
            if current_date.month == 4:  # April
                group_b_data.append({
                    "date": formatted_date,
                    "data": 0
                })
            else:
                group_b_data.append({
                    "date": formatted_date,
                    "data": None
                })
        else:
            if current_date.month == 4:  # April
                group_b_data.append({
                    "date": formatted_date,
                    "data": value
                })
            else:
                group_b_data.append({
                    "date": formatted_date,
                    "data": value
                })

        current_date += timedelta(days=1)

# Step 4: Write the data to the answer range (B20:B339)
start_row = 20
start_col = 2
end_row = start_row + len(group_b_data) - 1

for i, entry in enumerate(group_b_data):
    ws.cell(row=start_row + i, column=start_col, value=entry["date"])
    ws.cell(row=start_row + i, column=start_col + 1, value=entry["data"])

# Save the workbook
wb.save('output.xlsx')
